r-fork.r:
emit <- inline::cfunction(
  body = 'write(1, "native output\\n", 14);
          return R_NilValue;',
  includes = "#include <unistd.h>"
)
job <- parallel::mcparallel(emit())
invisible(parallel::mccollect(job))

r-fork-cat.r:
job <- parallel::mcparallel({
  out <- pipe("cat", "w")
  cat("hello from fork\n", file = out)
  close(out)
})
invisible(parallel::mccollect(job))
